mapper.select:
SELECT A.box_type_id AS "boxTypeId" /*일련번호*/ , A.box_type_cd AS "boxTypeCd" /*포장유형코드*/ , A.box_type_nm AS "boxTypeNm" /*포장유형명*/ , A.fixed_margin_rate AS "fixedMarginRate" /*고정마진율(%)*/ , A.loss_rate AS "lossRate" /*로스율(%)*/ , A.labor_cost AS "laborCost" /*인건비*/ , A.packing_cost AS "packingCost" /*포장비*/ , A.logistics_cost AS "logisticsCost" /*물류비*/ , A.margin_amt AS "marginAmt" /*마진*/ , A.total_cost AS "totalCost" /*부대비용 합계*/ , A.sort_seq AS "sortSeq" /*정렬순서*/ , A.use_yn AS "useYn" /*사용여부*/ , A.reg_user_id AS "regUserId" /*등록자 사번*/ , COALESCE(B.name, A.reg_user_id) AS "regUserNm" /*등록자 이름*/ , TO_CHAR(A.reg_dt, 'YYYY-MM-DD HH24:MI:SS') AS "regDt" /*등록일시*/ , A.upd_user_id AS "updUserId" /*수정자 사번*/ , COALESCE(C.name, A.upd_user_id) AS "updUserNm" /*수정자 이름*/ , TO_CHAR(A.upd_dt, 'YYYY-MM-DD HH24:MI:SS') AS "updDt" /*수정일시*/ FROM tb_box_type A LEFT JOIN employees B ON B.id = A.reg_user_id LEFT JOIN employees C ON C.id = A.upd_user_id WHERE A.factory_code = #{factoryCode} AND A.plant_code = #{plantCode}
AND A.use_yn = 'Y'
ORDER BY A.box_type_id , A.sort_seq , A.box_type_nm

SELECT MAX(CAST(box_type_cd AS INTEGER))
FROM tb_box_type
WHERE factory_code = #{factoryCode}
  AND plant_code   = #{plantCode}
  AND box_type_cd ~ '^[0-9]{6}$'

SELECT COUNT(*)
FROM tb_box_type
WHERE factory_code = #{factoryCode}
  AND plant_code   = #{plantCode}
  AND box_type_cd  = #{boxTypeCd}

SELECT COUNT(*)
FROM tb_box_type
WHERE factory_code = #{factoryCode}
  AND plant_code   = #{plantCode}
  AND box_type_cd  = #{boxTypeCd}
  AND use_yn       = 'Y'

  AND box_type_id <> #{boxTypeId}

mapper.insert:
INSERT INTO tb_box_type
(
  factory_code
, plant_code
, box_type_cd
, box_type_nm
, pack_qty
, pack_unit
, fixed_margin_rate
, loss_rate
, labor_cost
, packing_cost
, logistics_cost
, margin_amt
, sort_seq
, use_yn
, reg_user_id
) VALUES 
(
  #{factoryCode}
, #{plantCode}
, #{boxTypeCd}
, #{boxTypeNm}
, #{packQty, jdbcType=NUMERIC}     /*포장유형명 끝의 숫자(서비스가 읽음, 없으면 NULL)*/
, #{packUnit, jdbcType=VARCHAR}    /*포장유형명 끝의 단위(KG · G …)*/
, #{fixedMarginRate}
, #{lossRate}
, #{laborCost}
, #{packingCost}
, #{logisticsCost}
, #{marginAmt}
, #{sortSeq}
, #{useYn}
, #{userId, jdbcType=VARCHAR}
)

mapper.delete:
DELETE FROM tb_box_type
WHERE box_type_id  = #{boxTypeId}
  AND factory_code = #{factoryCode}
  AND plant_code   = #{plantCode}
